      const stat = await fs.readFile('/proc/' + pid + '/stat', 'utf8');
      return { running: stat.slice(stat.lastIndexOf(')') + 2).split(' ')[0] !== 'Z' };
    } catch (e) { if (e.code === 'ENOENT') return { running: false }; throw e; }
