        "start": as_int(r["start"]),
        "end": as_int(r["end"]),
        "dur": as_int(r["dur"]),
    } for r in rows]

    assert set(map(tuple_key, sched_csv)) == set(map(tuple_key, sched_json)), \
        "schedule.csv must match solution.json schedule on core fields (unordered)"

